import java.util.Scanner;

public class Main {
    public static int sumDoubles(int n) {
        int[] sequence = {1};
        int total = 0;
        for (int i = 0; i < n; i++) {
            total += sequence[sequence.length - 1];
            int[] newSequence = new int[sequence.length + 1];
            System.arraycopy(sequence, 0, newSequence, 0, sequence.length);
            newSequence[sequence.length] = sequence[sequence.length - 1] * 2;
            sequence = newSequence;
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int h = sc.nextInt();
        int n = sc.nextInt();

        int totalMoves = 0;
        int lBound = 1;
        int rBound = (int) Math.pow(2, h);
        int level = h;
        String direction = "L";

        for (int i = 0; i < h; i++) {
            double midPoint = (lBound + rBound) / 2.0;
            if (direction.equals("L")) {
                if (n > midPoint) {
                    totalMoves += sumDoubles(level) + 1;
                    lBound = (int) midPoint + 1;
                } else if (n < midPoint) {
                    rBound = (int) midPoint + ((lBound + rBound) % 2 != 0 ? 1 : 0) - 1;
                    totalMoves += 1;
                    direction = "R";
                }
                level -= 1;
            } else {
                if (n < midPoint) {
                    totalMoves += sumDoubles(level) + 1;
                    rBound = (int) midPoint + ((lBound + rBound) % 2 != 0 ? 1 : 0) - 1;
                } else if (n > midPoint) {
                    totalMoves += 1;
                    lBound = (int) midPoint + 1;
                    direction = "L";
                }
                level -= 1;
            }
        }
        System.out.println(totalMoves);
        sc.close();
    }
}
